CREATE OR REPLACE FUNCTION mso_manage._survey_anonymize(p_survey uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'mso_manage', 'public'
AS $function$
declare ids text[]; n int;
begin
  select coalesce(array_agg(id::text), '{}'::text[]) into ids from mso_manage.survey_questions where survey_id = p_survey and is_pii;
  update mso_manage.survey_responses
     set answers = answers - ids, respondent_id = null, respondent_name = null, anonymized_at = now()
   where survey_id = p_survey and anonymized_at is null;
  get diagnostics n = row_count;
  delete from mso_manage.survey_participants where survey_id = p_survey;
  update mso_manage.surveys set purged_at = now(), purged_count = n where id = p_survey and purged_at is null;
  return n;
end $function$

CREATE OR REPLACE FUNCTION mso_manage._survey_check_answers(p_survey uuid, p_answers jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'mso_manage', 'public'
AS $function$
declare q record; v jsonb; el jsonb; outp jsonb := '{}'::jsonb; txt text; byseq jsonb := '{}'::jsonb; ref jsonb; shown boolean;
begin
  if p_answers is null or jsonb_typeof(p_answers) <> 'object' then raise exception 'invalid_answers'; end if;
  if pg_column_size(p_answers) > 60000 then raise exception 'too_large'; end if;
  for q in select * from mso_manage.survey_questions where survey_id = p_survey order by seq loop
    shown := true;
    if q.show_if is not null then
      ref := byseq -> ((q.show_if ->> 'seq'));
      if ref is null then shown := false;
      elsif jsonb_typeof(ref) = 'array' then
        shown := exists (select 1 from jsonb_array_elements_text(ref) a where (q.show_if -> 'values') ? a);
      else
        shown := (q.show_if -> 'values') ? (ref #>> '{}');
      end if;
    end if;
    if not shown then continue; end if;
    v := p_answers -> q.id::text;
    if v is null or v = 'null'::jsonb
       or (jsonb_typeof(v) = 'string' and btrim(v #>> '{}') = '')
       or (jsonb_typeof(v) = 'array' and jsonb_array_length(v) = 0) then
      if q.required then raise exception 'required:%', q.seq; end if;
      continue;
    end if;
    if q.qtype = 'single' then
      if jsonb_typeof(v) <> 'string' or not (q.options ? (v #>> '{}')) then raise exception 'invalid:%', q.seq; end if;
      outp := outp || jsonb_build_object(q.id::text, v);
      byseq := byseq || jsonb_build_object(q.seq::text, v);
    elsif q.qtype = 'multi' then
      if jsonb_typeof(v) <> 'array' then raise exception 'invalid:%', q.seq; end if;
      for el in select e from jsonb_array_elements(v) e loop
        if jsonb_typeof(el) <> 'string' or not (q.options ? (el #>> '{}')) then raise exception 'invalid:%', q.seq; end if;
      end loop;
      v := (select jsonb_agg(distinct e) from jsonb_array_elements(v) e);
      outp := outp || jsonb_build_object(q.id::text, v);
      byseq := byseq || jsonb_build_object(q.seq::text, v);
    elsif q.qtype = 'text' then
      if jsonb_typeof(v) <> 'string' then raise exception 'invalid:%', q.seq; end if;
      txt := btrim(v #>> '{}');
      if length(txt) > 2000 then raise exception 'too_long:%', q.seq; end if;
      outp := outp || jsonb_build_object(q.id::text, txt);
    else
      txt := v #>> '{}';
      if txt !~ '^[1-5]$' then raise exception 'invalid:%', q.seq; end if;
      outp := outp || jsonb_build_object(q.id::text, txt::int);
      byseq := byseq || jsonb_build_object(q.seq::text, to_jsonb(txt::int));
    end if;
  end loop;
  return outp;
end $function$

CREATE OR REPLACE FUNCTION mso_manage._survey_new_code()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'mso_manage', 'public'
AS $function$
declare alpha constant text := 'abcdefghjkmnpqrstuvwxyz23456789'; b bytea; c text; i int;
begin
  loop
    b := decode(replace(gen_random_uuid()::text, '-', ''), 'hex');
    c := '';
    for i in 0..7 loop c := c || substr(alpha, (get_byte(b, i) % length(alpha)) + 1, 1); end loop;
    exit when not exists (select 1 from mso_manage.surveys where public_code = c);
  end loop;
  return c;
end $function$

CREATE OR REPLACE FUNCTION mso_manage.check_contract_file_extension()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'mso_manage', 'public'
AS $function$
declare
  v_ext text;
  v_allowed text[] := array['pdf','doc','docx','xls','xlsx','ppt','pptx','hwp','hwpx','jpg','jpeg','png','gif','txt','zip'];
begin
  v_ext := lower(regexp_replace(new.file_name, '^.*\.', ''));
  if v_ext is null or v_ext = new.file_name or not (v_ext = any(v_allowed)) then
    raise exception '허용되지 않는 파일 형식입니다: %', new.file_name
      using errcode = '23514';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION mso_manage.check_equipment_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'mso_manage', 'public'
AS $function$
begin
  if new.status is distinct from old.status or new.deleted_yn is distinct from old.deleted_yn then
    if not mso_manage.equip_scope_ok(old.clinic_code, old.team_code, true) then
      raise exception '장비 상태(사용중/폐기 등) 변경은 담당 장비관리자 또는 시스템관리자만 가능합니다.';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION mso_manage.cron_gate(p_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'mso_manage', 'public', 'vault'
AS $function$
declare v text; f text;
begin
  select decrypted_secret into v from vault.decrypted_secrets where name='cron_secret';
  if v is null or p_secret is null or p_secret <> v then return jsonb_build_object('ok', false); end if;
  select value into f from mso_manage.system_flags where key='alert_mail_enabled';
  return jsonb_build_object('ok', true, 'mail_enabled', coalesce(f,'true') = 'true');
end $function$

CREATE OR REPLACE FUNCTION mso_manage.generate_equipment_id()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'mso_manage', 'pg_temp'
AS $function$
declare
  v_year int := extract(year from now())::int;
  v_seq  int;
begin
  v_seq := mso_manage.next_doc_seq('ME', v_year);
  return 'ME-' || v_year || '-' || lpad(v_seq::text, 4, '0');
end;
$function$

CREATE OR REPLACE FUNCTION mso_manage.mark_contract_cleanup(p_ids uuid[], p_note text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'mso_manage', 'public'
AS $function$
declare v_me mso_manage.user_profiles%rowtype; v_n int;
begin
  select * into v_me from mso_manage.user_profiles where id = (select auth.uid()) and active='Y';
  if not found then raise exception '로그인이 필요합니다.'; end if;
  update mso_manage.contracts c
     set cleanup_checked_at = now(), cleanup_checked_by = v_me.user_name, cleanup_note = nullif(trim(p_note),'')
   where c.id = any(p_ids) and c.deleted_at is null
     and (coalesce(v_me.is_admin,false) or c.owner_id = v_me.id or mso_manage.has_level('contracts/form','edit'));
  get diagnostics v_n = row_count;
  perform mso_manage.run_insight_scan();
  return v_n;
end $function$

CREATE OR REPLACE FUNCTION mso_manage.reassign_linked_task_on_contract_owner_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'mso_manage', 'public'
AS $function$
declare
  v_new_owner mso_manage.user_profiles%rowtype;
begin
  if new.owner_id is distinct from old.owner_id and new.owner_id is not null then
    select * into v_new_owner from mso_manage.user_profiles where id = new.owner_id;
    if v_new_owner.email is not null then
      update mso_manage.task_items
        set user_email = v_new_owner.email,
            description = description || ' (담당자 변경으로 ' || coalesce(v_new_owner.user_name, v_new_owner.email) || '님에게 이관됨)',
            updated_at = now()
        where linked_contract_id = new.id and status <> 'DONE';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION mso_manage.refresh_insights(p_force boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'mso_manage', 'public'
AS $function$
declare v_last timestamptz;
begin
  if (select auth.uid()) is null then return; end if;
  select max(last_seen_at) into v_last from mso_manage.insights;
  if p_force or v_last is null or v_last < now() - interval '5 minutes' then
    perform mso_manage.run_insight_scan();
  end if;
end $function$

CREATE OR REPLACE FUNCTION mso_manage.request_notices()
 RETURNS TABLE(kind text, src text, id uuid, request_no text, title text, status text, memo text, who text, at timestamp with time zone, cnt integer, new_cnt integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'mso_manage', 'public'
AS $function$
declare uid uuid := auth.uid(); since timestamptz;
begin
  if uid is null or not exists (select 1 from mso_manage.user_profiles u where u.id = uid and u.active = 'Y') then return; end if;
  select s.seen_at into since from mso_manage.request_notice_seen s where s.user_id = uid;
  since := coalesce(since, now() - interval '7 days');

  -- 내 신청: 보완요청은 해결될 때까지 계속 보여준다
  return query (select 'supplement'::text, 'signage'::text, r.id, r.request_no, r.request_title, r.status, r.admin_memo, null::text, coalesce(r.processed_at, r.updated_at), null::int, null::int
                  from mso_manage.signage_requests r where r.requester_id = uid and r.status = 'SUPPLEMENT' order by coalesce(r.processed_at, r.updated_at) desc limit 20);
  -- 내 신청: 마지막 확인 이후 담당자가 처리한 건
  return query (select 'changed'::text, 'signage'::text, r.id, r.request_no, r.request_title, r.status, r.admin_memo, null::text, r.processed_at, null::int, null::int
                  from mso_manage.signage_requests r
                 where r.requester_id = uid and r.status in ('PROCESSING','ON_HOLD','REJECTED','COMPLETED')
                   and r.processed_at > since and r.processed_by is distinct from uid
                 order by r.processed_at desc limit 20);
  return query (select 'changed'::text, 'program'::text, r.id, r.request_no, r.request_title, r.status, r.admin_memo, null::text, r.processed_at, null::int, null::int
                  from mso_manage.program_requests r
                 where r.requester_id = uid and r.status in ('PROCESSING','ON_HOLD','REJECTED','COMPLETED')
                   and r.processed_at > since and r.processed_by is distinct from uid
                 order by r.processed_at desc limit 20);

  -- 담당자: 처리 대기와 보완 후 다시 접수된 건
  if mso_manage.has_level('signage/history', 'manager') then
    return query (select 'pending'::text, 'signage'::text, null::uuid, null::text, null::text, null::text, null::text, null::text, null::timestamptz,
                          count(*)::int, (count(*) filter (where r.created_at > since))::int
                     from mso_manage.signage_requests r where r.status = 'REQUESTED' having count(*) > 0);
    return query (select 'resubmitted'::text, 'signage'::text, r.id, r.request_no, r.request_title, r.status, null::text, r.requester_name, r.resubmitted_at, null::int, null::int
                    from mso_manage.signage_requests r where r.status = 'REQUESTED' and r.resubmitted_at > since
                    order by r.resubmitted_at desc limit 20);
  end if;
  if mso_manage.has_level('program-request/history', 'manager') then
    return query (select 'pending'::text, 'program'::text, null::uuid, null::text, null::text, null::text, null::text, null::text, null::timestamptz,
                          count(*)::int, (count(*) filter (where r.created_at > since))::int
                     from mso_manage.program_requests r where r.status = 'REQUESTED' having count(*) > 0);
  end if;
end $function$

CREATE OR REPLACE FUNCTION mso_manage.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
