$function$

CREATE OR REPLACE FUNCTION mso_manage.survey_anonymize_now(p_survey uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'mso_manage', 'public'
AS $function$
declare s mso_manage.surveys;
begin
  select * into s from mso_manage.surveys where id = p_survey and owner_id = auth.uid();
  if not found then raise exception 'not_owner'; end if;
  if s.status = 'draft' then raise exception 'draft'; end if;
  if s.status = 'open' then update mso_manage.surveys set status = 'closed' where id = p_survey; end if;
  return mso_manage._survey_anonymize(p_survey);
end $function$

CREATE OR REPLACE FUNCTION mso_manage.survey_biu()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'mso_manage', 'public'
AS $function$
begin
  if tg_op = 'INSERT' then
    new.owner_id := auth.uid();
    select user_name into new.owner_name from mso_manage.user_profiles where id = new.owner_id;
    if new.status <> 'draft' then new.status := 'draft'; end if;
    return new;
  end if;
  if new.owner_id <> old.owner_id or new.public_code <> old.public_code then raise exception 'immutable'; end if;
  if old.purged_at is not null and (new.status <> old.status or new.ends_at is distinct from old.ends_at) then
    raise exception 'purged'; end if;
  if mso_manage.survey_has_responses(old.id) then
    if new.mode <> old.mode or new.collects_pii <> old.collects_pii
       or new.pii_items is distinct from old.pii_items or new.pii_purpose is distinct from old.pii_purpose
       or coalesce(new.retention_days, 99999) > coalesce(old.retention_days, 99999) then
      raise exception 'locked_after_responses';
    end if;
  end if;
  if new.status = 'closed' and old.status <> 'closed' then new.closed_at := coalesce(new.closed_at, now()); end if;
  if new.status = 'open' and old.status = 'closed' then new.closed_at := null; end if;
  new.updated_at := now();
  return new;
end $function$

CREATE OR REPLACE FUNCTION mso_manage.survey_clinic_summary(p_survey uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'mso_manage', 'public'
AS $function$
declare s mso_manage.surveys; minn int := 5; apply_min boolean; cl record; q record; per jsonb := '{}'::jsonb; cells jsonb; cl_arr jsonb := '[]'::jsonb; cnt jsonb; o text; hidden boolean;
begin
  select * into s from mso_manage.surveys where id = p_survey;
  if not found or not (s.owner_id = auth.uid() or mso_manage.is_sysadmin()) then raise exception 'forbidden'; end if;
  apply_min := (s.mode <> 'staff_named') or s.purged_at is not null;
  for cl in select r.code, count(*) n from mso_manage._survey_resp_clinic(s.id) r group by 1 order by 1 loop
    hidden := apply_min and cl.n < minn;
    cl_arr := cl_arr || jsonb_build_object('code', cl.code, 'name', coalesce((select c.clinic_name from mso_manage.clinics c where c.clinic_code = cl.code), cl.code), 'n', cl.n, 'hidden', hidden);
  end loop;
  for q in select * from mso_manage.survey_questions where survey_id = s.id and qtype in ('single','multi','rating') and not (is_pii and s.purged_at is not null) order by seq loop
    cells := '{}'::jsonb;
    for cl in select r.code, count(*) n from mso_manage._survey_resp_clinic(s.id) r group by 1 loop
      if apply_min and cl.n < minn then continue; end if;
      if q.qtype = 'rating' then
        cells := cells || jsonb_build_object(cl.code, jsonb_build_object(
          'n', (select count(*) from mso_manage._survey_resp_clinic(s.id) r where r.code = cl.code and r.answers ? q.id::text),
          'avg', (select round(avg((r.answers ->> q.id::text)::numeric), 2) from mso_manage._survey_resp_clinic(s.id) r where r.code = cl.code and r.answers ? q.id::text)));
      else
        cnt := '{}'::jsonb;
        for o in select jsonb_array_elements_text(q.options) loop
          cnt := cnt || jsonb_build_object(o, (select count(*) from mso_manage._survey_resp_clinic(s.id) r where r.code = cl.code and r.answers ? q.id::text
                   and (case when jsonb_typeof(r.answers -> q.id::text) = 'array' then (r.answers -> q.id::text) ? o else (r.answers ->> q.id::text) = o end)));
        end loop;
        cells := cells || jsonb_build_object(cl.code, jsonb_build_object(
          'n', (select count(*) from mso_manage._survey_resp_clinic(s.id) r where r.code = cl.code and r.answers ? q.id::text), 'counts', cnt));
      end if;
    end loop;
    per := per || jsonb_build_object(q.id::text, cells);
  end loop;
  return jsonb_build_object('min_n', case when apply_min then minn else 1 end, 'clinics', cl_arr, 'per_q', per);
end $function$

CREATE OR REPLACE FUNCTION mso_manage.survey_participation(p_survey uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'mso_manage', 'public'
AS $function$
declare s mso_manage.surveys; res jsonb; pend jsonb := null;
begin
  select * into s from mso_manage.surveys where id = p_survey;
  if not found or not (s.owner_id = auth.uid() or mso_manage.is_sysadmin()) then raise exception 'forbidden'; end if;
  if s.mode = 'public' then return jsonb_build_object('applicable', false); end if;
  if s.purged_at is not null then return jsonb_build_object('applicable', false, 'purged', true); end if;
  with el as (
    select u.id, u.user_name, u.clinic_code from mso_manage.user_profiles u
     where u.active = 'Y'
       and (case when u.page_perms ? 'survey/respond' then coalesce(nullif(u.page_perms ->> 'survey/respond',''),'접근불가') else 'user' end) <> '접근불가'
  ), dn as (select p.user_id from mso_manage.survey_participants p where p.survey_id = s.id),
  byc as (
    select coalesce(e.clinic_code,'-') code, count(*) elig, count(d.user_id) done
      from el e left join dn d on d.user_id = e.id group by 1
  )
  select jsonb_build_object('applicable', true,
      'eligible', (select count(*) from el), 'done', (select count(*) from dn where user_id in (select id from el)),
      'by_clinic', coalesce((select jsonb_agg(jsonb_build_object('clinic_code', code, 'clinic_name', coalesce((select c.clinic_name from mso_manage.clinics c where c.clinic_code = byc.code), byc.code), 'eligible', elig, 'done', done) order by code) from byc), '[]'::jsonb))
    into res;
  if s.mode = 'staff_named' then
    select coalesce(jsonb_agg(jsonb_build_object('name', u.user_name, 'clinic', coalesce((select c.clinic_name from mso_manage.clinics c where c.clinic_code = u.clinic_code), u.clinic_code)) order by u.clinic_code, u.user_name), '[]'::jsonb) into pend
      from mso_manage.user_profiles u
     where u.active = 'Y'
       and (case when u.page_perms ? 'survey/respond' then coalesce(nullif(u.page_perms ->> 'survey/respond',''),'접근불가') else 'user' end) <> '접근불가'
       and not exists (select 1 from mso_manage.survey_participants p where p.survey_id = s.id and p.user_id = u.id);
    res := res || jsonb_build_object('pending', pend);
  end if;
  return res;
end $function$

CREATE OR REPLACE FUNCTION mso_manage.survey_staff_get(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'mso_manage', 'public'
AS $function$
declare s mso_manage.surveys; me uuid := auth.uid(); done boolean; mine jsonb;
begin
  if me is null or not exists (select 1 from mso_manage.user_profiles where id = me and active = 'Y') then raise exception 'login_required'; end if;
  if not mso_manage.has_level('survey/respond','user','user') then raise exception 'no_permission'; end if;
  select * into s from mso_manage.surveys where public_code = p_code and mode in ('staff_anon','staff_named');
  if not found or not mso_manage.survey_is_open(s) then raise exception 'not_open'; end if;
  done := exists (select 1 from mso_manage.survey_participants where survey_id = s.id and user_id = me);
  if done and s.resubmit = 'edit' then
    select r.answers into mine from mso_manage.survey_responses r where r.survey_id = s.id and r.respondent_id = me order by r.submitted_at desc limit 1;
  end if;
  return mso_manage._survey_public_view(s) || jsonb_build_object('already_done', done, 'my_answers', mine);
end $function$

CREATE OR REPLACE FUNCTION mso_manage.survey_staff_submit(p_code text, p_answers jsonb, p_consent boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'mso_manage', 'public'
AS $function$
declare s mso_manage.surveys; me uuid := auth.uid(); clean jsonb; nm text; clin text; dup boolean := false; n int; rid uuid;
begin
  select user_name, clinic_code into nm, clin from mso_manage.user_profiles where id = me and active = 'Y';
  if me is null or not found then raise exception 'login_required'; end if;
  if not mso_manage.has_level('survey/respond','user','user') then raise exception 'no_permission'; end if;
  select * into s from mso_manage.surveys where public_code = p_code and mode in ('staff_anon','staff_named');
  if not found or not mso_manage.survey_is_open(s) then raise exception 'not_open'; end if;
  if (s.collects_pii or s.mode = 'staff_named') and not coalesce(p_consent, false) then raise exception 'consent_required'; end if;
  clean := mso_manage._survey_check_answers(s.id, p_answers);
  begin
    insert into mso_manage.survey_participants (survey_id, user_id) values (s.id, me);
  exception when unique_violation then dup := true;
  end;
  if dup then
    if s.resubmit = 'edit' then
      update mso_manage.survey_responses set answers = clean, consented = coalesce(p_consent, false), submitted_at = now()
       where survey_id = s.id and respondent_id = me returning id into rid;
      if rid is null then raise exception 'already_done'; end if;
      insert into mso_manage.survey_response_meta (response_id, clinic_code) values (rid, clin)
        on conflict (response_id) do update set clinic_code = excluded.clinic_code;
      return jsonb_build_object('ok', true, 'updated', true);
    elsif s.resubmit <> 'multi' then
      raise exception 'already_done';
    end if;
  end if;
  insert into mso_manage.survey_responses (survey_id, answers, respondent_id, respondent_name, consented, channel)
    values (s.id, clean, case when s.mode = 'staff_named' then me end, case when s.mode = 'staff_named' then nm end, coalesce(p_consent, false), 'staff')
    returning id into rid;
  insert into mso_manage.survey_response_meta (response_id, clinic_code) values (rid, clin);
  return jsonb_build_object('ok', true);
end $function$

CREATE OR REPLACE FUNCTION mso_manage.sync_contract_counterparty_from_vendor()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'mso_manage', 'public'
AS $function$
begin
  if (new.vendor_name is distinct from old.vendor_name)
     or (new.biz_no is distinct from old.biz_no) then
    update mso_manage.contracts
    set counterparty_name = new.vendor_name,
        counterparty_biz_no = new.biz_no
    where vendor_id = new.id;
  end if;

  if (new.vendor_name is distinct from old.vendor_name) then
    update mso_manage.equipments
    set vendor = new.vendor_name
    where vendor_id = new.id;

    update mso_manage.sole_source_justifications
    set counterparty_company = new.vendor_name
    where vendor_id = new.id;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION mso_manage.sync_equipment_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'mso_manage', 'public'
AS $function$
declare
  lvl text[] := array['접근불가','user','edit','manager','admin'];
  cur text; want text; k text;
begin
  new.is_equipment_manager := (new.equipment_role is not null) or coalesce(new.is_admin,false);
  if new.equipment_role is not null then
    want := case new.equipment_role when 'dept_manager' then 'edit' else 'manager' end;
    new.page_perms := coalesce(new.page_perms,'{}'::jsonb);
    foreach k in array array['equipment/dashboard','equipment/list','equipment/detail','equipment/form'] loop
      cur := coalesce(new.page_perms->>k,'접근불가');
      if array_position(lvl,cur) < array_position(lvl, case when k='equipment/form' or new.equipment_role<>'dept_manager' then want else 'user' end) then
        new.page_perms := new.page_perms || jsonb_build_object(k, case when k='equipment/form' or new.equipment_role<>'dept_manager' then want else 'user' end);
      end if;
    end loop;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION mso_manage.sync_item_name(p_item_code text, p_source_table text, p_old_name text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'mso_manage'
AS $function$
DECLARE
  v_master_name text;
  v_count integer;
BEGIN
  IF not (mso_manage.current_user_is_admin() or mso_manage.has_level('master/supply','manager')) THEN
    RAISE EXCEPTION '자재 마스터 관리 권한이 없습니다.';
  END IF;

  SELECT item_name INTO v_master_name FROM mso_manage.items WHERE item_code = p_item_code;
  IF v_master_name IS NULL THEN
    RAISE EXCEPTION '자재코드(%)를 찾을 수 없습니다.', p_item_code;
  END IF;

  IF p_source_table = 'closing_stock' THEN
    UPDATE mso_manage.closing_stock
    SET item_name = v_master_name
    WHERE item_code = p_item_code AND item_name = p_old_name;
  ELSIF p_source_table = 'purchase_records' THEN
    UPDATE public.purchase_records
    SET item_name = v_master_name
    WHERE item_code = p_item_code AND item_name = p_old_name;
  ELSIF p_source_table = 'usage_records' THEN
    UPDATE public.usage_records
    SET item_name = v_master_name
    WHERE item_code = p_item_code AND item_name = p_old_name;
  ELSE
    RAISE EXCEPTION '알 수 없는 소스 테이블: %', p_source_table;
  END IF;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION mso_manage.validate_department_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'mso_manage', 'pg_temp'
AS $function$
declare
  v_parent_clinic_id uuid;
  v_cursor uuid;
  i int;
begin
  if new.parent_dept_id is null then
    return new;
  end if;

  if new.parent_dept_id = new.id then
    raise exception '자기 자신을 상위 부서로 지정할 수 없습니다.';
  end if;

  if not exists (select 1 from mso_manage.departments where id = new.parent_dept_id) then
    raise exception '존재하지 않는 상위 부서입니다.';
  end if;

  select clinic_id into v_parent_clinic_id from mso_manage.departments where id = new.parent_dept_id;

  -- [수정] 상위 부서가 특정 의원에 속하지 않는 Unit(clinic_id is null, 예: MSO전략Unit)인 경우엔
  -- 하위 부서가 어느 의원 소속이든 상관없이 허용한다 — Unit은 여러 의원에 걸친
  -- 최상위 조직 단위이기 때문이다. 상위 부서가 특정 의원 소속인 일반 부서라면
  -- 기존처럼 같은 의원 소속이어야 한다.
  if v_parent_clinic_id is not null and v_parent_clinic_id is distinct from new.clinic_id then
    raise exception '상위 부서는 같은 의원 소속이어야 합니다.';
  end if;

  v_cursor := new.parent_dept_id;
  for i in 1..1000 loop
    exit when v_cursor is null;
    if v_cursor = new.id then
      raise exception '순환 참조된 상위 부서 구조는 허용되지 않습니다.';
    end if;
    select parent_dept_id into v_cursor from mso_manage.departments where id = v_cursor;
  end loop;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.stats_agg(p_type text, p_dim text, p_filters jsonb DEFAULT '{}'::jsonb, p_basic jsonb DEFAULT NULL::jsonb, p_conds jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t text; qty text; sup text; vt text; amt text; dt text; w text; g1 text; g2 text; q text; res jsonb;
begin
  if p_type = 'purchase' then t:='purchase_records'; qty:='quantity'; sup:='supply_amount'; vt:='vat_amount'; amt:='total_amount'; dt:='received_date';
  elsif p_type = 'usage' then t:='usage_records'; qty:='usage_qty'; sup:='usage_supply'; vt:='usage_vat'; amt:='usage_total'; dt:='usage_date';
  else raise exception 'invalid type %', p_type; end if;
  w := public.stats_where_(p_filters, p_basic, p_conds);

  if p_dim = 'item' then
    q := format($f$
      with b as (select *, row_number() over (order by ym, uploaded_at, id) rn from public.%1$I where %2$s),
      k as (select b.*, btrim(coalesce(item_code,'')) code, coalesce(nullif(item_name,''),'(미확인)') nm,
                   coalesce(%4$I,0) q, coalesce(%5$I,0) s, coalesce(%6$I,0) v, coalesce(%7$I,0) a, coalesce(%8$I::text,'') d from b)
      select coalesce(jsonb_agg(jsonb_build_object(
          'code', code, 'name', name, 'qty', qty, 'supply', supply, 'vat', vat, 'amount', amount, 'cnt', cnt,
          'n_priced', n_priced, 'first_price', first_price, 'last_price', last_price) order by rn), '[]'::jsonb)
      from (
        select max(code) code, (array_agg(nm order by rn))[1] name,
               sum(q) qty, sum(s) supply, sum(v) vat, sum(a) amount, count(*) cnt, min(rn) rn,
               count(*) filter (where q > 0) n_priced,
               (array_agg(s / q order by d, rn) filter (where q > 0))[1] first_price,
               (array_agg(s / q order by d desc, rn desc) filter (where q > 0))[1] last_price
        from k group by case when code <> '' then 'code:' || code else 'name:' || nm end
      ) s $f$, t, w, null, qty, sup, vt, amt, dt);
  else
    if p_dim = 'branch' then g1 := $x$coalesce(nullif(branch,''),'(미확인)')$x$; g2 := 'null::text';
    elsif p_dim = 'dept' then g1 := $x$coalesce(nullif(dept,''),'(미확인)')$x$; g2 := 'null::text';
    elsif p_dim = 'ym' then g1 := $x$coalesce(nullif(ym,''),'(미확인)')$x$; g2 := 'null::text';
    elsif p_dim = 'type' then g1 := 'null::text'; g2 := 'null::text';
    elsif p_dim = 'vendor' then g1 := $x$nullif(vendor_biz_no,'')$x$; g2 := $x$coalesce(nullif(vendor_name,''),'(미확인)')$x$;
    else raise exception 'invalid dim %', p_dim; end if;
    q := format($f$
      with b as (select *, row_number() over (order by ym, uploaded_at, id) rn from public.%1$I where %2$s)
      select coalesce(jsonb_agg(jsonb_build_object('g1', g1, 'g2', g2, 'it', it, 'qty', qty, 'supply', supply,
               'vat', vat, 'amount', amount, 'cnt', cnt) order by rn), '[]'::jsonb)
      from (
        select %3$s g1, %4$s g2, coalesce(nullif(item_type,''),'미분류') it,
               sum(coalesce(%5$I,0)) qty, sum(coalesce(%6$I,0)) supply, sum(coalesce(%7$I,0)) vat, sum(coalesce(%8$I,0)) amount,
               count(*) cnt, min(rn) rn
        from b group by 1, 2, 3
      ) s $f$, t, w, g1, g2, qty, sup, vt, amt);
  end if;
  execute q into res;
  return res;
end $function$

CREATE OR REPLACE FUNCTION public.stats_cond_(c jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare col text := c->>'col';
begin
  if col is null or col not in ('vendor_name','dept','item_type','item_name','item_code') then
    return 'false';
  end if;
  if c->>'op' = 'in' then
    return format('lower(coalesce(%I,'''')) = any (%L::text[])', col,
      (select coalesce(array_agg(x), '{}') from jsonb_array_elements_text(c->'vals') x));
  end if;
  return format('strpos(lower(coalesce(%I,'''')), %L) > 0', col, c->>'val');
end $function$

CREATE OR REPLACE FUNCTION public.stats_item_rows(p_type text, p_key text, p_filters jsonb DEFAULT '{}'::jsonb, p_basic jsonb DEFAULT NULL::jsonb, p_conds jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t text; w text := public.stats_where_(p_filters, p_basic, p_conds); kw text; res jsonb;
begin
  if p_type = 'purchase' then t := 'purchase_records'; elsif p_type = 'usage' then t := 'usage_records'; else raise exception 'invalid type %', p_type; end if;
  if p_key like 'code:%' then
    kw := format('btrim(coalesce(item_code,'''')) = %L', substr(p_key, 6));
  elsif p_key like 'name:%' then
    kw := format('btrim(coalesce(item_code,'''')) = '''' and coalesce(nullif(item_name,''''),''(미확인)'') = %L', substr(p_key, 6));
  else raise exception 'invalid key'; end if;
  execute format('select coalesce(jsonb_agg(to_jsonb(t) order by t.ym, t.uploaded_at, t.id), ''[]''::jsonb) from public.%I t where %s and %s', t, w, kw) into res;
  return res;
end $function$

CREATE OR REPLACE FUNCTION public.stats_where_(p_filters jsonb, p_basic jsonb, p_conds jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare w text := 'true'; acc text := null; c jsonb; i int := 0;
begin
  p_filters := coalesce(p_filters, '{}'::jsonb);
  if coalesce(p_filters->>'branch','')   <> '' then w := w || format(' and branch = %L', p_filters->>'branch'); end if;
  if coalesce(p_filters->>'ymFrom','')   <> '' then w := w || format(' and ym >= %L', p_filters->>'ymFrom'); end if;
  if coalesce(p_filters->>'ymTo','')     <> '' then w := w || format(' and ym <= %L', p_filters->>'ymTo'); end if;
  if coalesce(p_filters->>'itemType','') <> '' then w := w || format(' and item_type = %L', p_filters->>'itemType'); end if;
  if coalesce(p_filters->>'dept','')     <> '' then w := w || format(' and dept = %L', p_filters->>'dept'); end if;
  if coalesce(p_filters->>'vendorBizNo','') <> '' then w := w || format(' and vendor_biz_no = %L', p_filters->>'vendorBizNo');
  elsif coalesce(p_filters->>'vendor','') <> '' then w := w || format(' and vendor_name = %L', p_filters->>'vendor'); end if;

  if p_basic is not null and jsonb_typeof(p_basic) = 'object' then
    w := w || ' and ' || public.stats_cond_(p_basic);
  end if;

  if p_conds is not null and jsonb_typeof(p_conds) = 'array' then
    for c in select * from jsonb_array_elements(p_conds) loop
      i := i + 1;
      if i = 1 then acc := public.stats_cond_(c);
      elsif upper(coalesce(c->>'comb','AND')) = 'OR' then acc := '(' || acc || ' or ' || public.stats_cond_(c) || ')';
      else acc := '(' || acc || ' and ' || public.stats_cond_(c) || ')';
      end if;
    end loop;
    if acc is not null then w := w || ' and ' || acc; end if;
  end if;
  return w;
end $function$

CREATE OR REPLACE FUNCTION public.survey_public_get(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'mso_manage', 'public'
AS $function$
declare s mso_manage.surveys;
begin
  select * into s from mso_manage.surveys where public_code = p_code and mode = 'public';
  if not found or not mso_manage.survey_is_open(s) then raise exception 'not_open'; end if;
  return mso_manage._survey_public_view(s);
end $function$

CREATE OR REPLACE FUNCTION public.survey_public_submit(p_code text, p_answers jsonb, p_consent boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'mso_manage', 'public'
AS $function$
declare s mso_manage.surveys; clean jsonb; recent int;
begin
  select * into s from mso_manage.surveys where public_code = p_code and mode = 'public';
  if not found or not mso_manage.survey_is_open(s) then raise exception 'not_open'; end if;
  if s.collects_pii and not coalesce(p_consent, false) then raise exception 'consent_required'; end if;
  select count(*) into recent from mso_manage.survey_responses where survey_id = s.id and submitted_at > now() - interval '1 minute';
  if recent >= 60 then raise exception 'rate_limited'; end if;
  clean := mso_manage._survey_check_answers(s.id, p_answers);
  insert into mso_manage.survey_responses (survey_id, answers, consented, channel)
    values (s.id, clean, coalesce(p_consent, false), 'external');
  return jsonb_build_object('ok', true);
end $function$
